#define OUT_OF_BOUNDS      1                                                   //!< When the user tries to read or write memory outside it's allowed or available space.
#define NOT_ENOUGH_SPACE   2                                                   //!< Not enough memory to store the information required.
#define OVERFLOW           3                                                   //!< 
#define INVALID_OPERATION  4                                                   //!< The operation performed is not valid.
#define UNKOWN             5                                                   //!< An unkown or not documented error happend.
#define NO_CARD            6                                                   //!< Warning there is no tag being read.
#define NOT_DEFINED        7                                                   //!< A pointer has NULL in it.
#define LOOP_BREAK         8                                                   //!< It was necessary to break an infinite loop.

